document.addEventListener('keydown',e=>{if(e.metaKey&&e.key.toLowerCase()==='k'){e.preventDefault();commandPalette();}else if(e.metaKey&&e.key.toLowerCase()==='b'){e.preventDefault();if(!$('#buildButton').disabled)build();}else if(e.metaKey&&e.key.toLowerCase()==='o'){e.preventDefault();openProject();}else if(e.key==='F5'){e.preventDefault();e.shiftKey?debugAction('stop'):actions.toggleRun();}else if(e.key==='F10'){e.preventDefault();if(S.debug==='paused')debugAction('next');}else if(e.key==='F11'){e.preventDefault();if(S.debug==='paused')debugAction('stepi');}});
async function boot(){try{const b=await api('bootstrap');Object.assign(S,{recent:b.recent,device:b.device,tools:b.tools,ports:b.ports});E.setDevice(S.device.registers);$('#toolStatus').textContent=S.tools.every(t=>t.available)?'XC8 2.46 · MPLAB 6.20':'Toolchain needs setup';welcome();renderSidebar();renderInspector();renderPanel();controls();if(b.testMode)setTimeout(()=>uiTest(b.testProject),200);else if(b.initialProject)await loaded(await api('open',{path:b.initialProject}));}catch(e){toast(e.message,true);welcome();renderInspector();renderPanel();}}
async function uiTest(path){const checks=[];try{
 await loaded(await api('open',{path}));checks.push({name:'Open MPLAB project in native WebKit',ok:!!S.active});
 const original=E.content();E.replace('; UI integration save check\n'+original);await saveAll();const read=await api('read',{path:S.active});checks.push({name:'Edit and save through native bridge',ok:read.content.includes('UI integration save check')});
 view('config');const reten=$('[data-config="RETEN"]');reten.value='OFF';reten.dispatchEvent(new Event('change'));$('#applyConfig').click();await saveAll();checks.push({name:'Apply configuration without duplicating alias fields',ok:/CONFIG\s+RETEN\s*=\s*OFF/.test(E.content())&&((E.content().match(/CONFIG\s+EB(?:TR|RT)0\s*=/g)||[]).length===1)});
 await build();checks.push({name:'Production build',ok:$('#buildStatus').textContent.includes('succeeded')});
 checks.push({name:'Stopwatch inherits the selected project clock and defaults to per-run timing',ok:Number($('#stopwatchClock').value)===S.project.clockMHz&&!$('#stopwatchAccumulate').checked});$('#stopwatchClock').value='4';await startDebug();checks.push({name:'Stopwatch begins at zero with clock locked',ok:S.stopwatch?.cycles==='0'&&$('#stopwatchClock').disabled&&!$('#resetStopwatch').disabled});checks.push({name:'Start simulator',ok:S.debug==='paused'});
 for(let i=0;i<5;i++){const r=await api('debugAction',{action:'stepi',names:names()});applyInspection(r);}
 checks.push({name:'Stopwatch displays executed cycles after stepping',ok:Number(S.stopwatch?.cycles)>0&&$('#stopwatchCycles').textContent.includes('instruction cycles')});
 const beforeStopwatchReset=JSON.stringify(S.location);$('#resetStopwatch').click();while(S.busy)await new Promise(r=>setTimeout(r,20));checks.push({name:'Reset stopwatch button clears time without moving CPU',ok:S.stopwatch?.cycles==='0'&&$('#stopwatchTime').textContent==='0 ns'&&JSON.stringify(S.location)===beforeStopwatchReset});
 checks.push({name:'Live WREG after stepping',ok:!!S.values.WREG&&S.values.WREG!=='Symbol does not exist.'});
 view('device');checks.push({name:'Device reference',ok:$$('#registerTable tr').length>200});
 view('config');checks.push({name:'Configuration editor',ok:$$('[data-config]').length>50});
 await debugAction('stop');
 const newPath=path.replace(/\/[^/]+$/, '/CreatedInterruptUIProject.X');
 await loaded(await api('new',{path:newPath,template:'interrupt'}));checks.push({name:'Creates MPLAB-compatible interrupt project',ok:E.content().includes('highISR:')});
 S.watches=['irq_count','INTCON','INTCON2','INTCON3'];const source=E.content(),idleLine=source.split('\n').findIndex(l=>l.includes('nop     ; idle loop'))+1,isrLine=source.split('\n').findIndex(l=>l.includes('incf    irq_count'))+1;
 async function until(test){const deadline=Date.now()+5000;while(!test()){if(Date.now()>deadline)throw Error('Timed out waiting for breakpoint UI');await new Promise(r=>setTimeout(r,30));}}
 async function gutterClick(line,margin=false){E.go(line);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const number=$$('.cm-lineNumbers .cm-gutterElement').find(el=>el.textContent===String(line)&&el.style.visibility!=='hidden');if(!number)throw Error('Line number is not visible');const rect=number.getBoundingClientRect(),gutter=$('.cm-breakpoint-gutter').getBoundingClientRect(),x=margin?(gutter.left+gutter.right)/2:(rect.left+rect.right)/2,y=(rect.top+rect.bottom)/2;const target=document.elementFromPoint(x,y);if(!target?.closest(margin?'.cm-breakpoint-gutter':'.cm-lineNumbers'))throw Error('Breakpoint click missed gutter');target.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,clientX:x,clientY:y,button:0}));await until(()=>!S.busy);await new Promise(r=>requestAnimationFrame(r));}
 await gutterClick(idleLine);checks.push({name:'Line-number click queues breakpoint before debugging and draws dot',ok:S.breakpoints.length===1&&!!$('.cm-breakpoint')});
 await gutterClick(idleLine,true);checks.push({name:'Left-margin click removes breakpoint and dot immediately',ok:S.breakpoints.length===0&&!$('.cm-breakpoint')});
 await gutterClick(idleLine,true);await startDebug();checks.push({name:'Starting debugger installs the selected breakpoint',ok:S.breakpoints.length===1&&Number.isInteger(S.breakpoints[0].id)});
 await debugAction('continue');await until(()=>S.debug==='paused'&&S.location.line===idleLine);checks.push({name:'Continue stops at breakpoint created by gutter click',ok:S.location.line===idleLine});
 await gutterClick(idleLine,true);await gutterClick(isrLine);checks.push({name:'Paused gutter click installs and draws ISR breakpoint',ok:S.breakpoints.length===1&&S.breakpoints[0].line===isrLine&&!!$('.cm-breakpoint')});
 panel('interrupts');checks.push({name:'Interrupt panel enabled in simulator',ok:!$('#triggerInterrupt').disabled});await api('triggerInterrupt',{source:'INT0'});await debugAction('continue');await until(()=>S.debug==='paused'&&S.location.line===isrLine);await debugAction('stepi');checks.push({name:'ISR executes through native UI workflow',ok:formatHex(S.values.irq_count)==='0x01'});
 view('files');panel('interrupts');renderInspector();$('#toast').hidden=true;if(S.location.line)E.go(S.location.line);await new Promise(r=>setTimeout(r,600));
 await api('uiTestDone',{checks,ok:checks.every(c=>c.ok),errors:[],registers:S.values,location:S.location});
 }catch(e){await api('uiTestDone',{checks,ok:false,error:e.message,stack:e.stack});}}
